using System.Windows.Forms;
namespace Astera {
sealed partial class LibraryForm {
    ProjectCatalog projectCatalog;DiscoverScroller discoverScroll;Panel discoverFilters;TextBox discoverSearch;Button discoverCategory;
    string discoverCategoryValue="All projects",discoverDetailId="";int featuredIndex;
    DiscoverArtwork featuredSurface;Label featuredTitle,featuredSummary,featuredBadge;CatalogProject featuredProject;
    readonly Dictionary<string,Image> discoverImages=new Dictionary<string,Image>();readonly HashSet<string> discoverImagePending=new HashSet<string>();
    readonly CancellationTokenSource discoverStop=new CancellationTokenSource();readonly System.Windows.Forms.Timer discoverClock=new System.Windows.Forms.Timer{Interval=6500};bool catalogChecked,layingOutDiscover,catalogOnlineFresh;Task catalogLoadTask;
    Panel BuildDiscoverPage(){
        projectCatalog=DiscoverCatalog.Bundled();var page=new Panel{Dock=DockStyle.Fill,Padding=new Padding(28,12,20,18),Visible=false,BackColor=BackColor};
        discoverScroll=new DiscoverScroller{Dock=DockStyle.Fill,BackColor=BackColor};page.Controls.Add(discoverScroll);
        discoverFilters=new Panel{Dock=DockStyle.Top,Height=48};
        discoverSearch=new TextBox{Width=290,Location=new Point(0,7),BackColor=Color.FromArgb(29,38,59),ForeColor=Color.White,Font=UiTheme.Text(14),AccessibleName="Search projects"};
        discoverSearch.HandleCreated+=delegate{SearchCue(discoverSearch.Handle,0x1501,new IntPtr(1),"Search projects…");};discoverSearch.TextChanged+=delegate{if(discoverDetailId.Length==0)RenderDiscover();};
        discoverCategory=Button("All projects ▾",delegate{ShowDiscoverCategories();});discoverCategory.Location=new Point(308,0);discoverFilters.Controls.Add(discoverSearch);discoverFilters.Controls.Add(discoverCategory);page.Controls.Add(discoverFilters);
        page.Controls.Add(new Label{Dock=DockStyle.Top,Height=58,Text="Welcome to Astera. Find another world to get lost in.",Font=UiTheme.Text(20,true),ForeColor=Color.White});
        discoverScroll.Content.Resize+=delegate{LayoutDiscoverContent();};
        discoverClock.Tick+=delegate{if(primaryPage==1&&discoverDetailId.Length==0&&Visible&&WindowState!=FormWindowState.Minimized&&ContainsFocus&&UiEffects.Enabled){featuredIndex++;ShowFeatured();}};
        page.VisibleChanged+=delegate{discoverClock.Enabled=page.Visible&&UiEffects.Enabled;if(page.Visible&&!previewMode)LoadOnlineCatalog();};
        Disposed+=delegate{discoverStop.Cancel();discoverClock.Dispose();foreach(var image in discoverImages.Values)image.Dispose();discoverImages.Clear();};
        RenderDiscover();return page;
    }
    IEnumerable<CatalogProject> FilteredDiscover(){string text=(discoverSearch.Text??"").Trim();return projectCatalog.Projects.Where(p=>(discoverCategoryValue=="All projects"||discoverCategoryValue=="Coming soon"&&p.Status=="coming-soon"||p.Category==discoverCategoryValue)&&(p.Title+" "+p.Summary+" "+p.Category).IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0);}
    void ShowDiscoverCategories(){var menu=AsteraMenuRenderer.Create(menuComponents);foreach(string value in new[]{"All projects","Coming soon"}.Concat(projectCatalog.Projects.Select(p=>p.Category).Distinct().OrderBy(x=>x))){string category=value;var item=new ToolStripMenuItem(category){Checked=category==discoverCategoryValue};item.Click+=delegate{discoverCategoryValue=category;discoverCategory.Text=category+" ▾";RenderDiscover();};menu.Items.Add(item);}menu.Closed+=delegate{BeginInvoke((Action)(()=>menu.Dispose()));};menu.Show(discoverCategory,new Point(0,discoverCategory.Height));}
    void ClearDiscover(){foreach(Control child in discoverScroll.Content.Controls.Cast<Control>().ToArray()){discoverScroll.Content.Controls.Remove(child);child.Dispose();}featuredSurface=null;discoverScroll.MoveTo(0);}
    void RenderDiscover(){if(discoverScroll==null||IsDisposed)return;ClearDiscover();discoverFilters.Visible=discoverDetailId.Length==0;var content=discoverScroll.Content;
        if(discoverDetailId.Length>0){var selected=projectCatalog.Projects.FirstOrDefault(p=>p.Id==discoverDetailId);if(selected!=null){RenderDiscoverDetail(selected);return;}discoverDetailId="";discoverFilters.Visible=true;}
        var filtered=FilteredDiscover().ToArray();bool browse=String.IsNullOrWhiteSpace(discoverSearch.Text)&&discoverCategoryValue=="All projects";
        if(browse){BuildFeatured();content.Controls.Add(new Label{Text="Explore our worlds",Font=UiTheme.Text(21,true),ForeColor=Color.White,Tag="grid-heading"});}
        if(filtered.Length==0)content.Controls.Add(new Label{Text="No projects match your search.",ForeColor=Muted,Tag="empty"});
        foreach(var p in filtered){var project=p;var card=new Card{Tag=project.Id,Padding=new Padding(12)};var art=new DiscoverArtwork{Dock=DockStyle.Fill,CatalogKey=DiscoverCatalog.ImageKey(project.Artwork),Artwork=CatalogArt(project.Artwork)};art.Click+=delegate{ShowDiscoverProject(project.Id);};
            var title=new Label{Text=project.Title,Dock=DockStyle.Bottom,Height=30,Font=UiTheme.Text(18,true),ForeColor=Color.White};var category=new Label{Text=project.Category+(project.Status=="coming-soon"?" · Coming soon":""),Dock=DockStyle.Bottom,Height=27,ForeColor=Muted};var action=Button("View project →",delegate{ShowDiscoverProject(project.Id);});action.Dock=DockStyle.Bottom;card.Controls.Add(art);card.Controls.Add(title);card.Controls.Add(category);card.Controls.Add(action);content.Controls.Add(card);}
        LayoutDiscoverContent();
    }
    void BuildFeatured(){featuredSurface=new DiscoverArtwork{Shade=true,Tag="featured"};featuredBadge=new Label{Text="FEATURED PROJECT",ForeColor=Color.LightSteelBlue,BackColor=Color.Transparent,Location=new Point(22,18),Size=new Size(500,23),Font=UiTheme.Text(11,true)};featuredTitle=new Label{ForeColor=Color.White,BackColor=Color.Transparent,Location=new Point(22,52),Size=new Size(620,50),Font=UiTheme.Text(32,true)};featuredSummary=new Label{ForeColor=Color.White,BackColor=Color.Transparent,Location=new Point(22,110),Size=new Size(620,52),Font=UiTheme.Text(15)};var open=Button("View project →",delegate{if(featuredProject!=null)ShowDiscoverProject(featuredProject.Id);});open.SetBounds(22,178,180,40);var previous=Button("‹",delegate{featuredIndex--;ShowFeatured();});previous.SetBounds(216,178,48,40);previous.MinimumSize=new Size(48,40);previous.AutoSize=false;var next=Button("›",delegate{featuredIndex++;ShowFeatured();});next.SetBounds(274,178,48,40);next.MinimumSize=new Size(48,40);next.AutoSize=false;featuredSurface.Controls.AddRange(new Control[]{featuredBadge,featuredTitle,featuredSummary,open,previous,next});discoverScroll.Content.Controls.Add(featuredSurface);ShowFeatured();}
    void ShowFeatured(){if(featuredSurface==null)return;var projects=projectCatalog.Projects.Where(p=>p.Featured).ToArray();if(projects.Length==0)projects=projectCatalog.Projects.Take(1).ToArray();int index=((featuredIndex%projects.Length)+projects.Length)%projects.Length;featuredProject=projects[index];featuredSurface.CatalogKey=DiscoverCatalog.ImageKey(featuredProject.Artwork);featuredSurface.Artwork=CatalogArt(featuredProject.Artwork);featuredTitle.Text=featuredProject.Title;featuredSummary.Text=featuredProject.Summary;featuredBadge.Text="FEATURED PROJECT · "+(featuredProject.Status=="coming-soon"?"COMING SOON":featuredProject.Category.ToUpperInvariant());featuredSurface.Invalidate();}
    void LayoutDiscoverContent(){if(discoverScroll==null||layingOutDiscover)return;layingOutDiscover=true;try{var content=discoverScroll.Content;int width=Math.Max(200,content.Width);if(discoverDetailId.Length>0){LayoutDiscoverDetail(width);return;}int y=0;if(featuredSurface!=null){featuredSurface.SetBounds(0,0,width-10,236);featuredTitle.Width=featuredSummary.Width=Math.Max(200,Math.Min(650,width-48));y=252;}
        var heading=content.Controls.Cast<Control>().FirstOrDefault(c=>Object.Equals(c.Tag,"grid-heading"));if(heading!=null){heading.SetBounds(0,y,width,42);y+=50;}
        var cards=content.Controls.OfType<Card>().ToArray();int columns=width>=1400?3:2;int cardWidth=(width-16*columns)/columns;for(int i=0;i<cards.Length;i++)cards[i].SetBounds((i%columns)*(cardWidth+16),y+(i/columns)*246,cardWidth,230);
        var empty=content.Controls.Cast<Control>().FirstOrDefault(c=>Object.Equals(c.Tag,"empty"));if(empty!=null)empty.SetBounds(0,y,width,50);content.Height=y+Math.Max(1,(cards.Length+columns-1)/columns)*246;}finally{layingOutDiscover=false;}}
    void ShowDiscoverProject(string id){if(!projectCatalog.Projects.Any(p=>p.Id==id))return;discoverDetailId=id;discoverClock.Stop();RenderDiscover();}
    void RenderDiscoverDetail(CatalogProject project){var content=discoverScroll.Content;var back=Button("← Back to Discover",delegate{discoverDetailId="";RenderDiscover();discoverClock.Enabled=Visible&&primaryPage==1&&UiEffects.Enabled;});back.Tag="detail-back";content.Controls.Add(back);
        var hero=new DiscoverArtwork{Shade=true,CatalogKey=DiscoverCatalog.ImageKey(project.Artwork),Artwork=CatalogArt(project.Artwork),Tag="detail-hero"};var title=new Label{Text=project.Title,Font=UiTheme.Text(32,true),ForeColor=Color.White,BackColor=Color.Transparent,Location=new Point(22,40),Size=new Size(750,55)};var summary=new Label{Text=project.Summary,Font=UiTheme.Text(15),ForeColor=Color.White,BackColor=Color.Transparent,Location=new Point(22,105),Size=new Size(750,65)};hero.Controls.Add(title);hero.Controls.Add(summary);content.Controls.Add(hero);
        var actions=new FlowLayoutPanel{Tag="detail-actions",WrapContents=false};string action=CatalogActionLabel(project);var primary=Button(action,async delegate{if(project.Package!=null){var game=ManagedNebula;if(game!=null&&File.Exists(game.Executable)&&!ManagedUpdateReady(game)){ReloadGames(game);SelectPrimaryPage(0);}else await InstallManagedProject(project);}else if(project.LibraryKind>=0)OpenDiscoverGame(project.LibraryKind);else if(!String.IsNullOrEmpty(project.OfficialUrl))OpenCatalogUrl(project.OfficialUrl);});primary.Enabled=project.Status=="available"&&(project.Package!=null||project.LibraryKind>=0||project.OfficialUrl.Length>0);actions.Controls.Add(primary);if(project.LibraryKind>=0&&project.OfficialUrl.Length>0)actions.Controls.Add(Button("Official project ↗",delegate{OpenCatalogUrl(project.OfficialUrl);}));content.Controls.Add(actions);
        AddDiscoverText("About",project.Description);AddDiscoverText("Requirements",project.Requirements);AddDiscoverText("Latest update",String.IsNullOrWhiteSpace(project.Notes)?"No patch notes available yet.":project.Notes);
        if(project.Screenshots.Count>0){var gallery=new FlowLayoutPanel{Tag="detail-gallery",WrapContents=true};foreach(var image in project.Screenshots){var item=image;var thumb=new DiscoverArtwork{Width=220,Height=124,Margin=new Padding(0,0,12,12),CatalogKey=DiscoverCatalog.ImageKey(item),Artwork=CatalogArt(item),Cursor=Cursors.Hand};thumb.Click+=delegate{hero.CatalogKey=DiscoverCatalog.ImageKey(item);hero.Artwork=CatalogArt(item);hero.Invalidate();};gallery.Controls.Add(thumb);}content.Controls.Add(gallery);}
        LayoutDiscoverContent();}
    void AddDiscoverText(string heading,string text){var label=new Label{Text=heading+"\r\n\r\n"+(String.IsNullOrWhiteSpace(text)?"More details coming soon.":text),Font=UiTheme.Text(14),ForeColor=Color.FromArgb(210,220,240),Tag="detail-text"};discoverScroll.Content.Controls.Add(label);}
    void LayoutDiscoverDetail(int width){int y=0;foreach(Control child in discoverScroll.Content.Controls){string tag=child.Tag as string;if(tag=="detail-back"){child.SetBounds(0,y,210,40);y+=52;}else if(tag=="detail-hero"){child.SetBounds(0,y,width-10,230);foreach(Control text in child.Controls)text.Width=Math.Max(200,Math.Min(750,width-48));y+=246;}else if(tag=="detail-actions"){child.SetBounds(0,y,width-10,48);y+=66;}else if(tag=="detail-text"){int h=TextRenderer.MeasureText(child.Text,child.Font,new Size(Math.Max(100,width-32),32767),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix).Height+24;child.SetBounds(8,y,width-32,h);y+=h+20;}else if(tag=="detail-gallery"){int per=Math.Max(1,(width-10)/232);int rows=(child.Controls.Count+per-1)/per;child.SetBounds(0,y,width-10,rows*136);y+=rows*136;}}discoverScroll.Content.Height=y+20;}
    string CatalogActionLabel(CatalogProject project){if(project.Status=="coming-soon")return "Coming soon";if(project.Package!=null){var installed=ManagedNebula;return installed==null||!File.Exists(installed.Executable)?(String.IsNullOrEmpty(project.Package.Url)?"Install from ZIP":"Install"):ManagedUpdateReady(installed)?"Update":"Manage in Library";}if(project.LibraryKind<0)return "Open official project ↗";bool ready=project.LibraryKind==0?Directory.Exists(store.Settings.Profile):project.LibraryKind==1?LocalStarDash.IsValid(store.Settings.StarDashExecutable):FtlInstalled()!=null;return ready?"Manage in Library":"Set up in Library";}
    void OpenCatalogUrl(string url){var uri=new Transport().Address(url);if(MessageBox.Show(this,"Open this official project page?\r\n\r\n"+uri.Host,"Open project",MessageBoxButtons.YesNo,MessageBoxIcon.Information)==DialogResult.Yes)System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}
    Image CatalogArt(CatalogImage art){string key=DiscoverCatalog.ImageKey(art);Image image;if(discoverImages.TryGetValue(key,out image))return image;if(art.Resource.Length>0){image=GameArtwork.Load(art.Resource);if(image!=null)discoverImages[key]=image;return image;}if(art.Url.Length>0&&!previewMode)LoadCatalogArt(art);return null;}
    async void LoadCatalogArt(CatalogImage art){string key=DiscoverCatalog.ImageKey(art);if(discoverImagePending.Count>=32||!discoverImagePending.Add(key))return;Image loaded=null;try{loaded=await Task.Run(()=>DiscoverCatalog.ReadRemoteImage(art,Path.Combine(store.Root,"discover-artwork"),discoverStop.Token));if(IsDisposed||discoverStop.IsCancellationRequested){loaded.Dispose();return;}discoverImages[key]=loaded;RefreshDiscoverArtwork(discoverScroll.Content);}catch(Exception error){if(loaded!=null)loaded.Dispose();if(!discoverStop.IsCancellationRequested)AsteraDiagnostics.Write("Discover artwork unavailable",error);}}
    void RefreshDiscoverArtwork(Control root){foreach(Control child in root.Controls){var surface=child as DiscoverArtwork;Image ready;if(surface!=null&&discoverImages.TryGetValue(surface.CatalogKey,out ready)){surface.Artwork=ready;surface.Invalidate();}RefreshDiscoverArtwork(child);}}
    async void LoadOnlineCatalog(){await RefreshDiscoverCatalog(false);}
    Task RefreshDiscoverCatalog(bool force){if(catalogLoadTask!=null&&!catalogLoadTask.IsCompleted)return catalogLoadTask;catalogLoadTask=LoadOnlineCatalogCore(force);return catalogLoadTask;}
    async Task LoadOnlineCatalogCore(bool force){if(catalogChecked&&!force)return;catalogOnlineFresh=false;catalogChecked=true;string cached=Path.Combine(store.Root,"discover-catalog.signed.json");try{var catalog=await Task.Run(()=>{if(!File.Exists(cached))return null;return DiscoverCatalog.Verify(File.ReadAllBytes(cached),channel.PublicKeyXml);});if(catalog!=null&&!IsDisposed){projectCatalog=catalog;RenderDiscover();}}catch(Exception error){AsteraDiagnostics.Write("Cached Discover catalog unavailable",error);}
        try{byte[] bytes=null;var catalog=await Task.Run(()=>{using(var stream=new MemoryStream()){new Transport().Get(DiscoverCatalog.FeedUrl,stream,512*1024,-1,discoverStop.Token,null);bytes=stream.ToArray();var parsed=DiscoverCatalog.Verify(bytes,channel.PublicKeyXml);string next=cached+".next";File.WriteAllBytes(next,bytes);if(File.Exists(cached))File.Replace(next,cached,null);else File.Move(next,cached);return parsed;}});if(!IsDisposed){catalogOnlineFresh=true;projectCatalog=catalog;RenderDiscover();}}catch(Exception error){if(!discoverStop.IsCancellationRequested)AsteraDiagnostics.Write("Online Discover catalog unavailable; using offline catalog",error);}}
}
}
